def _parse_sounds_like(self, this: exp.Expr | None) -> exp.Expr | None:
    sounds_index = self._index - 1
    previous = self._tokens[sounds_index - 1] if sounds_index > 0 else None

    # `NOT SOUNDS LIKE` is not a MySQL predicate. Do not let the generic range parser
    # interpret it as the negation of `SOUNDS LIKE`.
    if previous and previous.token_type == TokenType.NOT:
        self._retreat(sounds_index)
        return None

    if not self._match(TokenType.LIKE):
        self._retreat(sounds_index)
        return None

    return self.expression(
        exp.EQ(
            this=self.expression(exp.Soundex(this=this)),
            expression=self.expression(exp.Soundex(this=self._parse_term())),
        )
    )

